def minimum_robbery_capability(nums,k):
    def possible(limit):
        robbed=0;previous=-2
        for index,value in enumerate(nums):
            if value<=limit and index>previous+1:robbed+=1;previous=index
        return robbed>=k
    low=min(nums);high=max(nums)
    while low<high:
        middle=(low+high)//2
        if possible(middle):high=middle
        else:low=middle+1
    return low

